<?php foreach($data['repairs'] as $repair): $is_cleanup=($repair['metadata']['source']['kind']??'')==='targeted-cleanup'; ?><article class="card" data-owner="<?=$escape($cs_owner($repair))?>"><h3><?=$escape($cs_label($repair))?></h3><p class="path"><?=$escape($repair['target'])?></p><?php if(!$repair['site_availability']['available']): ?><p class="notice alert alert-info"><?=$escape($repair['site_availability']['message'])?><br><small class="path">Original root: <?=$escape($repair['root']??'Unknown')?></small></p><?php endif ?><p><strong><?=$escape($repair['status'])?></strong> <?=$escape($repair['error']??'')?></p>
<?php if(isset($repair['metadata']['preview'])): ?><p><?=$is_cleanup?'Targeted cleaning':'Replacement'?> source: <?=$escape($repair['metadata']['replacement']['source'])?></p><?php if($is_cleanup): ?><p>Removes <?=$escape($repair['metadata']['replacement']['removed_bytes'])?> bytes. All remaining bytes are retained.</p><?php foreach($repair['metadata']['replacement']['recipes'] as $recipe): ?><p><?=$escape($recipe['family'])?> · Definition <?=$escape($recipe['id'])?> · Offset <?=$escape($recipe['offset'])?><br><a href="<?=$escape($recipe['source'])?>" target="_blank" rel="noopener noreferrer">Research by <?=$escape($recipe['author'])?></a><br><small class="path">Fragment SHA-256: <?=$escape($recipe['prefix_sha256'])?></small></p><?php endforeach ?><?php endif ?><?php if(($repair['metadata']['replacement']['kind']??'')==='hestia-backup'): ?><p class="path">Backup member: <?=$escape($repair['metadata']['replacement']['member'])?> · Compression: <?=$escape($repair['metadata']['replacement']['compression'])?><br>Compressed data SHA-256: <?=$escape($repair['metadata']['replacement']['compressed_member_sha256'])?></p><?php endif ?><?php if(isset($repair['metadata']['replacement']['warning'])): ?><p role="note"><?=$escape($repair['metadata']['replacement']['warning'])?></p><?php endif ?><?php if(isset($repair['metadata']['validation'])): ?><p>Scanned with: <?=$escape(implode(', ',$repair['metadata']['validation']['engines']))?> · <?= $escape(gmdate('Y-m-d H:i:s',(int)$repair['metadata']['validation']['at'])) ?> UTC</p><p class="path">Scanning data: <?=$escape($repair['metadata']['generation'])?></p><?php endif ?><p class="path">Current SHA-256: <?=$escape($repair['metadata']['preview']['before_sha256']??'Absent')?><br>Replacement SHA-256: <?=$escape($repair['metadata']['preview']['after_sha256'])?></p><?php if(isset($repair['metadata']['creation'])): ?><p>Original file: absent. New file permissions: 0644; new folders: 0755. Ownership follows the hosting account. Undo removes only this exact created file and retains other files and folders.</p><?php endif ?><button class="button cs-repair-review" data-plan="<?=$escape($repair['id'])?>"><?=$is_cleanup?'Review cleaning changes':'Review replacement'?></button><pre style="white-space:pre-wrap" aria-live="polite"></pre><?php endif ?>
<?php if($repair['site_availability']['available'] && $repair['status']==='ready'): ?><button disabled data-capability="<?=$is_cleanup?'cleanup':'repair'?>" class="button cs-repair-apply" data-action="repair-apply" data-plan_id="<?=$escape($repair['id'])?>"><?=$is_cleanup?'Apply reviewed cleaning':'Apply reviewed replacement'?></button><?php endif ?>
<?php if($repair['site_availability']['available'] && in_array($repair['status'],['repaired','verified','recheck_failed'])): ?><button class="button" data-action="repair-undo" data-plan_id="<?=$escape($repair['id'])?>"><?=$is_cleanup?'Undo cleaning':'Undo repair'?></button><?php endif ?>
<?php if($repair['site_availability']['available'] && $repair['status']==='recovery_required'): ?><button class="button" data-action="repair-recover" data-plan_id="<?=$escape($repair['id'])?>">Recover interrupted operation</button><?php endif ?></article><?php endforeach ?>
